<div class="form-section-title"><span class="step-number">01</span><div><strong>Informasi produk</strong><small>Identitas dan pengelompokan barang</small></div></div>
<div class="form-grid"><div class="form-field"><label for="sku">SKU / Kode produk <span class="required">*</span></label><input class="form-control" id="sku" name="sku" required maxlength="40" value="<?php echo e(old('sku', $product->sku)); ?>" placeholder="BRG-001"><small>Kode unik, gunakan huruf, angka, strip atau garis bawah.</small></div>
<div class="form-field"><label for="name">Nama produk <span class="required">*</span></label><input class="form-control" id="name" name="name" required maxlength="150" value="<?php echo e(old('name', $product->name)); ?>" placeholder="Contoh: Keyboard Mechanical"></div>
<div class="form-field"><label for="category_id">Kategori <span class="required">*</span></label><select class="form-control" id="category_id" name="category_id" required><option value="">Pilih kategori</option><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $category): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($category->id); ?>" <?php if(old('category_id', $product->category_id) == $category->id): echo 'selected'; endif; ?>><?php echo e($category->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div>
<div class="form-field"><label for="supplier_id">Pemasok</label><select class="form-control" id="supplier_id" name="supplier_id"><option value="">Belum ditentukan</option><?php $__currentLoopData = $suppliers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $supplier): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($supplier->id); ?>" <?php if(old('supplier_id', $product->supplier_id) == $supplier->id): echo 'selected'; endif; ?>><?php echo e($supplier->company_name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div>
<div class="form-field full-field"><label for="description">Deskripsi</label><textarea class="form-control" id="description" name="description" rows="3" maxlength="2000" placeholder="Informasi tambahan produk..."><?php echo e(old('description', $product->description)); ?></textarea></div></div>
<div class="form-section-title"><span class="step-number">02</span><div><strong>Harga & persediaan</strong><small>Harga, satuan, dan batas minimum persediaan</small></div></div>
<div class="form-grid"><div class="form-field"><label for="purchase_price">Harga beli (Rp) <span class="required">*</span></label><input class="form-control" type="number" id="purchase_price" name="purchase_price" min="0" step="0.01" required value="<?php echo e(old('purchase_price', $product->purchase_price ?? 0)); ?>"></div>
<div class="form-field"><label for="selling_price">Harga jual (Rp) <span class="required">*</span></label><input class="form-control" type="number" id="selling_price" name="selling_price" min="0" step="0.01" required value="<?php echo e(old('selling_price', $product->selling_price ?? 0)); ?>"><small>Harga jual harus sama dengan atau lebih tinggi dari harga beli.</small></div>
<div class="form-field"><label for="min_stock">Batas minimum stok <span class="required">*</span></label><input class="form-control" type="number" id="min_stock" name="min_stock" min="0" max="100000000" required value="<?php echo e(old('min_stock', $product->min_stock ?? 5)); ?>"></div>
<div class="form-field"><label for="unit">Satuan <span class="required">*</span></label><input class="form-control" id="unit" name="unit" required maxlength="30" value="<?php echo e(old('unit', $product->unit ?? 'pcs')); ?>" placeholder="pcs / box / kg"></div>
<div class="form-field full-field"><label for="location">Lokasi penyimpanan</label><input class="form-control" id="location" name="location" maxlength="80" value="<?php echo e(old('location', $product->location)); ?>" placeholder="Contoh: Rak A-01"></div>
<div class="form-field"><label class="toggle-field"><input type="checkbox" name="is_active" value="1" <?php if(old('is_active', $product->exists ? $product->is_active : true)): echo 'checked'; endif; ?>><span class="toggle-ui"></span><span><strong>Produk aktif</strong><small>Produk aktif dapat dipilih untuk transaksi stok.</small></span></label></div></div>
<?php if($product->exists): ?><div class="info-note"><span>i</span><p>Saldo saat ini <strong><?php echo e(number_format($product->stock)); ?> <?php echo e($product->unit); ?></strong>. Perubahan jumlah stok hanya dilakukan melalui transaksi stok agar riwayat inventaris tetap konsisten.</p></div><?php else: ?><div class="info-note"><span>i</span><p>Saldo awal produk otomatis <strong>0</strong>. Tambahkan persediaan melalui menu <strong>Transaksi Stok → Stok Masuk</strong>.</p></div><?php endif; ?>
